CREATE TABLE IF NOT EXISTS leases(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT NOT NULL,tenant_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,rent DECIMAL(10,2),deposit DECIMAL(10,2) DEFAULT 1000,status ENUM('active','ended') DEFAULT 'active',note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(tenant_id) REFERENCES users(id));
